+++ b/include/gpac/tools.h
@@ -526,8 +526,8 @@ u8 gf_cenc_key_info_get_iv_size(const u8 *key_info, u32 key_info_size, u32 key_i
 /*!
 \brief validate a CENC key info chunk

-Checks key record bounds and IV lengths. Nonzero per-sample and constant IV
-sizes must be 8 or 16 bytes; zero is allowed for a clear default.
+Checks key record bounds and per-sample IV lengths. A nonzero per-sample IV
+size must be 8 or 16 bytes; zero selects a constant IV or a clear default.
 \param key_info CENC key info buffer
 \param key_info_size CENC key info buffer size
 \return GF_TRUE if this chunk looks like a CENC key info buffer, GF_FALSE otherwise
diff --git a/src/isomedia/drm_sample.c b/src/isomedia/drm_sample.c
index 955f919..6592cab 100644
--- a/src/isomedia/drm_sample.c
+++ b/src/isomedia/drm_sample.c
@@ -794,6 +794,9 @@ GF_Err gf_isom_set_cenc_protection(GF_ISOFile *the_file, u32 trackNumber, u32 de
 		}
 		if (key_info_size>37) key_info_size = 37;
 		memcpy(sinf->info->tenc->key_info, key_info, key_info_size);
+		//a constant IV is stored inline after the KID; keep it within the key_info storage
+		if (!sinf->info->tenc->key_info[3] && (key_info_size >= 21) && (sinf->info->tenc->key_info[20] > 16))
+			sinf->info->tenc->key_info[20] = 16;
 	}
 	return GF_OK;
 }
